def table(group):
 lines=['| ID / name | Defined at (file#decl) | Plain-English meaning / status | Class | Owner | Removing job / branch | Evidence |','|---|---|---|:---:|---|---|---|']
 for r in rows:
  if r['group'] not in group:continue
  meaning=r['meaning']+(' **OVERLAP: do not add as independent gate.**' if r['status']=='overlap' else '')
  cells=[r['id']+' / `'+r['name']+'`','`'+r['definition']+'`',meaning,r['classification'],r['owner'],r['job'],r['evidence']]
  lines.append('| '+' | '.join(c.replace('|','\\|').replace('\n',' ') for c in cells)+' |')
 return '\n'.join(lines)+'\n'
